<?php
require_once __DIR__.'/backend/authorization.php';
require_once __DIR__.'/backend/db.php';
requireCustomer();
$uid=(int)$_SESSION['user_id'];$bid=(int)($_GET['booking_id']??0);$result=(string)($_GET['result']??'');
$s=$conn->prepare("SELECT b.id,b.service_type,b.amount,b.status,p.status payment_status FROM bookings b JOIN payments p ON p.booking_id=b.id WHERE b.id=? AND b.user_id=? LIMIT 1");$s->bind_param('ii',$bid,$uid);$s->execute();$booking=$s->get_result()->fetch_assoc();if(!$booking)redirectTo('booking-history.php');
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payment Status | Oh My Gracious</title><link rel="stylesheet" href="css/style.css"></head><body><header class="navbar"><div class="logo">Oh My Gracious</div><nav><a href="user-dashboard.php">Dashboard</a><a href="booking.php">Book</a><a href="booking-history.php">History</a><a href="account.php">My Account</a><a href="logout.php" class="logout-btn">Logout</a></nav></header><main class="page-wrap narrow"><section class="panel center-panel"><p class="eyebrow">ONLINE PAYMENT</p><h1><?= $booking['payment_status']==='Paid'?'Payment Confirmed':'Payment Processing'?></h1><?php if($booking['payment_status']==='Paid'):?><div class="alert success">PayMongo confirmed your payment. Your appointment payment status is now Paid.</div><a class="btn primary" href="receipt.php?id=<?=$bid?>">View Receipt</a><?php elseif($result==='cancelled'):?><div class="alert warning">You left PayMongo checkout before payment was confirmed. Your appointment is still reserved. You may try payment again from Booking History.</div><?php else:?><div class="alert info">You returned from PayMongo. Payment is only marked Paid after the verified PayMongo webhook reaches the system. Refresh Booking History in a moment.</div><?php endif;?><div class="button-row"><a class="btn secondary" href="booking-history.php">Booking History</a></div></section></main></body></html>
